examples.template:
MonarchWorkspaceSwitcher(
    initiallyOpen = true,
    workspaces = listOf(
        MonarchWorkspaceOption({{workspaces.0.id}}, {{workspaces.0.name}}, handle = {{workspaces.0.handle}}),
        MonarchWorkspaceOption({{workspaces.1.id}}, {{workspaces.1.name}}, handle = {{workspaces.1.handle}}),
        MonarchWorkspaceOption({{workspaces.2.id}}, {{workspaces.2.name}}, handle = {{workspaces.2.handle}}, keywords = {{workspaces.2.keywords}}),
    ),
    selection = workspace,
    onSelectionChange = { workspace = it },
    modifier = Modifier.width(240.dp),
    onCreate = {
        // The app opens its Create workspace screen.
    },
    onManage = { uriHandler.openUri({{manageHref}}) },
)

